package com.chainauth.auth;

import com.chainauth.auth.dto.*; import com.chainauth.security.JwtService; import com.chainauth.user.*; import org.springframework.http.HttpStatus; import org.springframework.security.authentication.*; import org.springframework.security.core.AuthenticationException; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.time.Instant; import java.util.*;

@Service public class AuthService {
 private final UserRepository users; private final PasswordEncoder encoder; private final AuthenticationManager authManager; private final JwtService jwt; private final TokenService tokens;
 public AuthService(UserRepository users,PasswordEncoder encoder,AuthenticationManager authManager,JwtService jwt,TokenService tokens){this.users=users;this.encoder=encoder;this.authManager=authManager;this.jwt=jwt;this.tokens=tokens;}
 public User register(RegisterRequest req){if(req.password().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>72)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Password must be at most 72 UTF-8 bytes");String email=normalize(req.email()); if(users.existsByEmail(email))throw new ResponseStatusException(HttpStatus.CONFLICT,"An account with this email already exists"); User u=new User();u.setName(req.name().trim());u.setEmail(email);u.setPasswordHash(encoder.encode(req.password()));u.setRoles(Set.of(Role.USER));u.setCreatedAt(Instant.now());u.setUpdatedAt(Instant.now());try{return users.save(u);}catch(org.springframework.dao.DuplicateKeyException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"An account with this email already exists");}}
 public Authenticated login(LoginRequest req){String email=normalize(req.email()); try{authManager.authenticate(new UsernamePasswordAuthenticationToken(email,req.password()));}catch(AuthenticationException e){throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password");} User u=users.findByEmail(email).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));String access=jwt.generate(u);TokenService.Issued refresh=tokens.issue(u.getId(),null);return new Authenticated(response(access,u),refresh.raw());}
 public Authenticated loginWithWallet(User u){if(!u.isEnabled())throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Account unavailable");String access=jwt.generate(u);TokenService.Issued refresh=tokens.issue(u.getId(),null);return new Authenticated(response(access,u),refresh.raw());}
 public Authenticated refresh(String raw){if(raw==null||raw.isBlank())throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Refresh session is invalid");RefreshToken old=tokens.consume(raw).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Refresh session is invalid or expired"));User u=users.findById(old.getUserId()).filter(User::isEnabled).orElseGet(()->{tokens.revokeFamily(old.getFamilyId());throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Account unavailable");});String access=jwt.generate(u);TokenService.Issued next=tokens.issue(u.getId(),old.getFamilyId());tokens.replace(old.getTokenHash(),tokens.hash(next.raw()));return new Authenticated(response(access,u),next.raw());}
 public void logout(String raw){if(raw!=null&&!raw.isBlank())tokens.revokeRaw(raw);}
 private AuthResponse response(String token,User u){return new AuthResponse(token,"Bearer",Instant.now().plusSeconds(jwt.getTtlSeconds()),view(u));}
 public AuthResponse.UserView view(User u){return new AuthResponse.UserView(u.getId(),u.getName(),u.getEmail(),u.getRoles().stream().map(Enum::name).collect(java.util.stream.Collectors.toUnmodifiableSet()));}
 public static String normalize(String email){return email.trim().toLowerCase(Locale.ROOT);}
 public record Authenticated(AuthResponse response,String refreshToken){}
}
